def verificar_metas_duplicadas(apps, schema_editor):
    """La restricción meta_item_funcionario_unica falla si ya hay metas repetidas: se informan antes, con su detalle."""
    Meta = apps.get_model('delegaciones_app', 'Meta')
    vistos, repetidas = set(), []
    for item_id, funcionario_id in Meta.objects.values_list('item_id', 'funcionario_id'):
        if (item_id, funcionario_id) in vistos:
            repetidas.append(f'ítem {item_id} / funcionario {funcionario_id}')
        vistos.add((item_id, funcionario_id))
    if repetidas:
        raise RuntimeError('Hay metas duplicadas (mismo ítem y funcionario); elimina las sobrantes antes de migrar: ' + ', '.join(repetidas))


